from collections import defaultdict

class Node:
    def __init__(self, position, parent=None):
        self.position = position  # (x, y) coordinate
        self.parent = parent  # Previous node in the path
        self.cost = 0  # Cost to reach this node

class PathSearch:
    def __init__(self, start, end, heuristic):
        self.start = start
        self.end = end
        self.heuristic = heuristic  # Function to calculate distance to the goal

    def _get_neighbors(self, node):
        neighbors = []
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            new_x = node.position[0] + dx
            new_y = node.position[1] + dy
            if 0 <= new_x < 10 and 0 <= new_y < 10:
                neighbor = self.create_neighbor(node, (new_x, new_y))
                neighbors.append(neighbor)
        return neighbors

    def create_neighbor(self, node, neighbor_pos):
        return Node(neighbor_pos, node)

    def a_star(self, grid):
        open_set = defaultdict(lambda: {"f": float("inf"), "g": float("inf"), "h": float("inf")})
        open_set[self.start] = {"f": 0, "g": 0, "h": self.heuristic(self.start, self.end)}
        closed_set = set()  
        visited = set()
        while open_set:
            current = sorted(open_set, key=lambda x: x["f"], reverse=True)[0]
            if current == self.end:
                path = []
                while current:
                    path.append(current.position)
                    current = current.parent
                return path[::-1]
            if current in closed_set:
                continue
            closed_set.add(current)
            visited.add(current)
            for neighbor in self._get_neighbors(current):
                neighbor_cost = current.cost + 1  
                neighbor_g = current.cost + neighbor_cost
                neighbor_f = neighbor_g + self.heuristic(neighbor, self.end)
                if neighbor not in open_set:
                    open_set[neighbor] = {"f": neighbor_f, "g": neighbor_g, "h": self.heuristic(neighbor, self.end)}
                elif neighbor_f < open_set[neighbor]["f"]:
                    open_set[neighbor]["g"] = neighbor_g
                    open_set[neighbor]["f"] = neighbor_f
        return None

    def heuristic(self, node, goal):
        # Example heuristic: Manhattan distance
        return abs(node[0] - goal[0]) + abs(node[1] - goal[1])


